from numbers import Real
import math

def most_correlated_columns(data):
    if not data or len(data) < 2:
        raise ValueError("data must contain at least two columns")

    # Type-check all values
    for col in data.values():
        for value in col:
            if not isinstance(value, Real):
                raise TypeError("columns must contain only numeric values")

    if any(len(col) == 0 for col in data.values()):
        raise ValueError("no data")

    names = list(data.keys())
    cols = [[float(v) for v in data[name]] for name in names]
    n = len(cols[0])

    means = [sum(col) / n for col in cols]

    deviations = []
    variances = []
    for col, mean in zip(cols, means):
        dev = [x - mean for x in col]
        deviations.append(dev)
        variances.append(sum(d * d for d in dev))

    best_pair = None
    best_abs = -1.0

    for i in range(len(names)):
        for j in range(i + 1, len(names)):
            denom = math.sqrt(variances[i] * variances[j])
            if denom == 0.0:
                r = 0.0
            else:
                cov = sum(a * b for a, b in zip(deviations[i], deviations[j]))
                r = cov / denom

            if abs(r) > best_abs:
                best_abs = abs(r)
                best_pair = (names[i], names[j])

    return best_pair
