import re
import math
from collections import Counter

def _clean(text):
    # Lowercase, then replace every run of non-letter/non-digit chars
    # (underscores included) with a single space.
    return re.sub(r'[^a-z0-9]+', ' ', text.lower())

def _lcs_length(a, b):
    # Standard LCS length using O(len(b)) memory.
    if len(a) < len(b):
        a, b = b, a

    prev = [0] * (len(b) + 1)

    for ca in a:
        curr = [0] * (len(b) + 1)
        for j, cb in enumerate(b, 1):
            if ca == cb:
                curr[j] = prev[j - 1] + 1
            else:
                curr[j] = max(prev[j], curr[j - 1])
        prev = curr

    return prev[-1]

def text_similarity_scores(text1, text2):
    c1 = _clean(text1)
    c2 = _clean(text2)

    words1 = c1.split()
    words2 = c2.split()

    # Cosine similarity over word counts
    if not words1 or not words2:
        cosine = 0.0
    else:
        cnt1 = Counter(words1)
        cnt2 = Counter(words2)

        dot = sum(cnt1[w] * cnt2.get(w, 0) for w in cnt1)
        norm1 = math.sqrt(sum(v * v for v in cnt1.values()))
        norm2 = math.sqrt(sum(v * v for v in cnt2.values()))

        cosine = dot / (norm1 * norm2)

    # Insert/delete-only similarity:
    # distance = len1 + len2 - 2*LCS, ratio = 1 - distance/(len1+len2)
    if not c1 and not c2:
        ratio = 1.0
    else:
        lcs = _lcs_length(c1, c2)
        ratio = (2.0 * lcs) / (len(c1) + len(c2))

    return (cosine, ratio)
