def fit_linear_regression(features, values):
    if len(features) != len(values):
        raise ValueError("features and values must have the same length")
    n = len(features)
    if n == 0:
        raise ValueError("at least one sample is required")

    p = len(features[0])
    for row in features:
        if len(row) != p:
            raise ValueError("all feature rows must have the same length")

    # Design matrix columns: intercept + features
    m = p + 1
    XtX = [[0.0] * m for _ in range(m)]
    Xty = [0.0] * m

    for row, y in zip(features, values):
        x = [1.0] + [float(v) for v in row]
        y = float(y)
        for i in range(m):
            Xty[i] += x[i] * y
            for j in range(m):
                XtX[i][j] += x[i] * x[j]

    # Solve normal equations XtX * beta = Xty using Gauss-Jordan elimination
    aug = [XtX[i] + [Xty[i]] for i in range(m)]

    for col in range(m):
        pivot = max(range(col, m), key=lambda r: abs(aug[r][col]))
        scale = max(
            (abs(aug[r][c]) for r in range(col, m) for c in range(col, m)),
            default=0.0,
        )
        if scale == 0.0 or abs(aug[pivot][col]) <= 1e-12 * scale:
            raise ValueError("singular normal equations; cannot fit unique OLS")

        if pivot != col:
            aug[col], aug[pivot] = aug[pivot], aug[col]

        pivot_val = aug[col][col]
        for j in range(col, m + 1):
            aug[col][j] /= pivot_val

        for r in range(m):
            if r != col:
                factor = aug[r][col]
                if factor != 0.0:
                    for j in range(col, m + 1):
                        aug[r][j] -= factor * aug[col][j]

    beta = [aug[i][m] for i in range(m)]

    return {
        "coefficients": [float(b) for b in beta[1:]],
        "intercept": float(beta[0]),
    }
