import math
from collections import Counter

def letter_count_correlations(strings):
    if not strings:
        return None

    counters = [Counter(s) for s in strings]
    letters = sorted({ch for c in counters for ch in c if 'a' <= ch <= 'z'})
    if not letters:
        return {}

    n = len(strings)
    counts = {ch: [c[ch] for c in counters] for ch in letters}

    sums = {ch: sum(counts[ch]) for ch in letters}
    sum_sqs = {ch: sum(v * v for v in counts[ch]) for ch in letters}
    sum_prods = {
        (x, y): sum(a * b for a, b in zip(counts[x], counts[y]))
        for x in letters
        for y in letters
    }

    result = {}
    for x in letters:
        row = {}
        var_x = n * sum_sqs[x] - sums[x] * sums[x]
        for y in letters:
            if x == y:
                row[y] = 1.0
                continue

            var_y = n * sum_sqs[y] - sums[y] * sums[y]
            denom = var_x * var_y
            numer = n * sum_prods[(x, y)] - sums[x] * sums[y]

            if denom == 0:
                row[y] = 0.0
            elif numer * numer == denom:
                row[y] = 1.0 if numer > 0 else -1.0
            else:
                r = numer / math.sqrt(denom)
                if r > 1.0:
                    r = 1.0
                elif r < -1.0:
                    r = -1.0
                row[y] = r

        result[x] = row

    return result
