import csv
import io
import math

def _is_number(value):
    try:
        return math.isfinite(float(value))
    except (TypeError, ValueError):
        return False

def normalize_numeric_columns(csv_text):
    reader = csv.reader(io.StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV text has no header row")

    rows = [row for row in reader if row]  # ignore blank lines
    if not rows:
        raise ValueError("no numeric columns")

    columns = {name: [] for name in header}
    for row in rows:
        for i, name in enumerate(header):
            columns[name].append(row[i] if i < len(row) else "")

    numeric_columns = []
    for name in header:
        values = columns[name]
        if values and all(_is_number(v) for v in values):
            numeric_columns.append(name)

    if not numeric_columns:
        raise ValueError("no numeric columns")

    result = {}
    for name in header:
        if name in numeric_columns:
            nums = [float(v) for v in columns[name]]
            lo = min(nums)
            hi = max(nums)

            if hi == lo:
                result[name] = [0.0 for _ in nums]
            else:
                result[name] = [(x - lo) / (hi - lo) for x in nums]
        else:
            result[name] = columns[name]

    return result
