from html.parser import HTMLParser

_VOID_TAGS = {
    "area", "base", "br", "col", "embed", "hr", "img", "input",
    "link", "meta", "param", "source", "track", "wbr",
}

class _FirstTagTextParser(HTMLParser):
    def __init__(self, tag_name):
        super().__init__(convert_charrefs=True)  # decodes HTML entities
        self.tag_name = tag_name.strip().lower()
        self.depth = 0
        self.found = False
        self.done = False
        self.parts = []

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()
        if self.done:
            return
        if tag == self.tag_name:
            if self.depth == 0:
                self.found = True
                if tag in _VOID_TAGS:
                    self.done = True
                    self.parts = []
                else:
                    self.depth = 1
                    self.parts = []
            else:
                self.depth += 1

    def handle_startendtag(self, tag, attrs):
        tag = tag.lower()
        if self.done:
            return
        if tag == self.tag_name and self.depth == 0:
            self.found = True
            self.done = True
            self.parts = []

    def handle_endtag(self, tag):
        tag = tag.lower()
        if self.done:
            return
        if self.depth > 0 and tag == self.tag_name:
            self.depth -= 1
            if self.depth == 0:
                self.done = True

    def handle_data(self, data):
        if self.depth > 0:
            self.parts.append(data)

    def get_text(self):
        if not self.found:
            return None
        text = "".join(self.parts)
        return text if text else None


def first_tag_text(html, tag):
    parser = _FirstTagTextParser(tag)
    parser.feed(html)
    parser.close()
    return parser.get_text()
```

This uses only the standard library, handles nested elements, decodes entities, and returns `None` when the first matching tag is missing or has empty text content.

