import csv
import io
import math

try:
    import numpy as np
except ImportError:
    np = None


def _parse_float(value, where):
    if value is None:
        raise ValueError(f"Missing value in {where}")
    s = value.strip()
    if s == "":
        raise ValueError(f"Missing value in {where}")
    try:
        x = float(s)
    except (TypeError, ValueError):
        raise ValueError(f"Non-numeric value in {where}: {value!r}")
    if not math.isfinite(x):
        raise ValueError(f"Non-numeric value in {where}: {value!r}")
    return x


def _read_csv(text):
    reader = csv.reader(io.StringIO(text))
    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV text has no header row")

    # Remove a possible BOM from the first header name.
    if header and header[0].startswith("\ufeff"):
        header[0] = header[0][1:]

    return header, list(reader)


def _solve_normal_equations(X, y):
    """Solve OLS normal equations without numpy."""
    n = len(X)
    if n == 0:
        raise ValueError("train_csv has no data rows")

    p = len(X[0])
    A = [[0.0] * p for _ in range(p)]
    b = [0.0] * p

    for row, yi in zip(X, y):
        for i in range(p):
            ri = row[i]
            b[i] += ri * yi
            Ai = A[i]
            for j in range(p):
                Ai[j] += ri * row[j]

    # Gaussian elimination with partial pivoting on [A | b]
    M = [A[i][:] + [b[i]] for i in range(p)]

    for col in range(p):
        pivot = max(range(col, p), key=lambda r: abs(M[r][col]))
        if abs(M[pivot][col]) < 1e-12:
            raise ValueError("Cannot fit a unique OLS model (singular normal equations)")
        if pivot != col:
            M[col], M[pivot] = M[pivot], M[col]

        piv = M[col][col]
        for r in range(col + 1, p):
            factor = M[r][col] / piv
            if factor != 0.0:
                for c in range(col, p + 1):
                    M[r][c] -= factor * M[col][c]

    beta = [0.0] * p
    for i in range(p - 1, -1, -1):
        s = M[i][p]
        for j in range(i + 1, p):
            s -= M[i][j] * beta[j]
        beta[i] = s / M[i][i]

    return beta


def predict_linear_regression(train_csv, test_csv, target):
    train_header, train_rows = _read_csv(train_csv)
    test_header, test_rows = _read_csv(test_csv)

    target_indices = [i for i, name in enumerate(train_header) if name == target]
    if not target_indices:
        raise ValueError(f"Target column {target!r} not found in train_csv")
    target_idx = target_indices[0]

    feature_indices = [i for i, name in enumerate(train_header) if name != target]
    feature_names = [train_header[i] for i in feature_indices]

    test_feature_indices = []
    for name in feature_names:
        try:
            test_feature_indices.append(test_header.index(name))
        except ValueError:
            raise ValueError(f"Test CSV is missing column {name!r}")

    X_train = []
    y_train = []

    needed_train_indices = feature_indices + [target_idx]

    for r, row in enumerate(train_rows, start=2):
        for idx in needed_train_indices:
            if idx >= len(row):
                raise ValueError(
                    f"Missing value in train_csv row {r} column {train_header[idx]!r}"
                )

        feats = [
            _parse_float(row[i], f"train_csv row {r} column {train_header[i]!r}")
            for i in feature_indices
        ]
        y_val = _parse_float(row[target_idx], f"train_csv row {r} column {target!r}")

        X_train.append([1.0] + feats)   # leading 1 is the intercept
        y_train.append(y_val)

    X_test = []
    for r, row in enumerate(test_rows, start=2):
        feats = []
        for name, idx in zip(feature_names, test_feature_indices):
            if idx >= len(row):
                raise ValueError(f"Missing value in test_csv row {r} column {name!r}")
            feats.append(_parse_float(row[idx], f"test_csv row {r} column {name!r}"))
        X_test.append([1.0] + feats)

    if not X_train:
        raise ValueError("train_csv has no data rows")

    if np is not None:
        X_train_np = np.array(X_train, dtype=float)
        y_train_np = np.array(y_train, dtype=float)
        beta = np.linalg.lstsq(X_train_np, y_train_np, rcond=None)[0]

        if not X_test:
            return []
        X_test_np = np.array(X_test, dtype=float)
        return [float(v) for v in X_test_np @ beta]

    beta = _solve_normal_equations(X_train, y_train)
    return [sum(b * x for b, x in zip(beta, row)) for row in X_test]
