import csv
from io import StringIO

def normalize_csv_columns(csv_text):
    reader = csv.reader(StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        return {}

    columns = {name: [] for name in header}

    for row in reader:
        if not row or all(cell.strip() == "" for cell in row):
            continue
        for i, name in enumerate(header):
            columns[name].append(float(row[i]))

    normalized = {}

    for name in header:
        values = columns[name]
        if not values:
            normalized[name] = []
            continue

        lo = min(values)
        hi = max(values)

        if lo == hi:
            normalized[name] = [0.0] * len(values)
        else:
            span = hi - lo
            normalized[name] = [(v - lo) / span for v in values]

    return normalized
