from html.parser import HTMLParser

class _DataTableParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.rows = []
        self.in_target = False
        self.done = False
        self.table_depth = 0
        self.target_depth = 0
        self.current_row = None
        self.current_cell = None

    def _close_cell(self):
        if self.current_cell is not None:
            if self.current_row is not None:
                self.current_row.append(''.join(self.current_cell))
            self.current_cell = None

    def _close_row(self):
        if self.current_row is not None:
            self._close_cell()
            self.rows.append(self.current_row)
            self.current_row = None

    def handle_starttag(self, tag, attrs):
        if self.done:
            return

        if tag == 'table':
            if not self.in_target:
                if dict(attrs).get('class') == 'data-table':
                    self.in_target = True
                    self.table_depth = 1
                    self.target_depth = 1
            else:
                self.table_depth += 1
            return

        if not self.in_target or self.table_depth != self.target_depth:
            return

        if tag == 'tr':
            self._close_row()
            self.current_row = []
        elif tag == 'td':
            if self.current_row is not None:
                self._close_cell()
                self.current_cell = []

    def handle_endtag(self, tag):
        if self.done:
            return

        if tag == 'table':
            if self.in_target:
                if self.table_depth == self.target_depth:
                    self._close_row()
                    self.in_target = False
                    self.done = True
                else:
                    self.table_depth -= 1
            return

        if not self.in_target or self.table_depth != self.target_depth:
            return

        if tag == 'tr':
            self._close_row()
        elif tag == 'td':
            self._close_cell()

    def handle_data(self, data):
        if self.in_target and self.current_cell is not None:
            self.current_cell.append(data)

    def result(self):
        if self.in_target:
            self._close_row()
        return self.rows


def extract_data_table_rows(html):
    parser = _DataTableParser()
    parser.feed(html)
    parser.close()
    return parser.result()
