import re
import html
from html.parser import HTMLParser

class _TextExtractor(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.parts = []
        self._in_raw_text = False

    def handle_starttag(self, tag, attrs):
        if tag.lower() in ("script", "style"):
            self._in_raw_text = True

    def handle_endtag(self, tag):
        if tag.lower() in ("script", "style"):
            self._in_raw_text = False

    def handle_data(self, data):
        # Normal text is already entity-decoded by convert_charrefs=True.
        # Inside script/style, HTMLParser leaves entities raw, so decode them here.
        if self._in_raw_text:
            data = html.unescape(data)
        self.parts.append(data)


def extract_phone_numbers(html_text):
    parser = _TextExtractor()
    parser.feed(html_text)
    parser.close()

    text = "".join(parser.parts)
    return re.findall(r"\+[0-9]+", text)
