from html.parser import HTMLParser

_PENDING = object()

class _ArticleParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.results = []      # container contexts in document order
        self.active = []       # currently open container contexts
        self.stack = []        # (tag, container_context, capture)
        self.captures = []     # currently open target captures

    def _remove_active(self, container):
        for i, ctx in enumerate(self.active):
            if ctx is container:
                del self.active[i]
                return

    def _remove_capture(self, cap):
        for i, c in enumerate(self.captures):
            if c is cap:
                del self.captures[i]
                return

    def handle_starttag(self, tag, attrs):
        attrs_dict = dict(attrs)
        classes = attrs_dict.get('class', '').split()

        container = None
        if tag == 'div' and 'container' in classes:
            container = {'title': None, 'date': None, 'author': None}
            self.results.append(container)
            self.active.append(container)

        capture = None
        if tag == 'h1':
            targets = [ctx for ctx in self.active if ctx['title'] is None]
            if targets:
                for ctx in targets:
                    ctx['title'] = _PENDING
                capture = {'tag': tag, 'fields': [('title', targets)], 'texts': []}
                self.captures.append(capture)

        elif tag == 'span':
            fields = []
            if 'date' in classes:
                targets = [ctx for ctx in self.active if ctx['date'] is None]
                if targets:
                    for ctx in targets:
                        ctx['date'] = _PENDING
                    fields.append(('date', targets))

            if 'author' in classes:
                targets = [ctx for ctx in self.active if ctx['author'] is None]
                if targets:
                    for ctx in targets:
                        ctx['author'] = _PENDING
                    fields.append(('author', targets))

            if fields:
                capture = {'tag': tag, 'fields': fields, 'texts': []}
                self.captures.append(capture)

        self.stack.append((tag, container, capture))

    def handle_data(self, data):
        # Data belongs to every currently open target element.
        for cap in self.captures:
            cap['texts'].append(data)

    def handle_endtag(self, tag):
        for i in range(len(self.stack) - 1, -1, -1):
            if self.stack[i][0] == tag:
                popped = self.stack[i:]
                del self.stack[i:]

                # Close innermost elements first.
                for _, container, capture in reversed(popped):
                    if capture is not None:
                        self._remove_capture(capture)
                        text = ''.join(capture['texts']).strip()
                        for field, targets in capture['fields']:
                            for ctx in targets:
                                if ctx[field] is _PENDING:
                                    ctx[field] = text

                    if container is not None:
                        self._remove_active(container)
                break

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)
        self.handle_endtag(tag)


def extract_article_info(html):
    parser = _ArticleParser()
    parser.feed(html)
    parser.close()

    def value(ctx, field, default):
        v = ctx[field]
        return default if v is None or v is _PENDING else v

    return [
        (
            value(ctx, 'title', 'No Title'),
            value(ctx, 'date', 'No Date'),
            value(ctx, 'author', 'No Author'),
        )
        for ctx in parser.results
    ]
