def _solve_linear_system(A, b):
    """Solve A x = b using Gaussian elimination with partial pivoting."""
    n = len(A)
    M = [A[i][:] + [b[i]] for i in range(n)]

    for col in range(n):
        pivot = max(range(col, n), key=lambda r: abs(M[r][col]))
        if abs(M[pivot][col]) < 1e-12:
            raise ValueError("singular matrix in linear regression")
        if pivot != col:
            M[col], M[pivot] = M[pivot], M[col]

        for row in range(col + 1, n):
            factor = M[row][col] / M[col][col]
            if factor != 0.0:
                for c in range(col, n + 1):
                    M[row][c] -= factor * M[col][c]

    x = [0.0] * n
    for i in range(n - 1, -1, -1):
        s = M[i][n]
        for j in range(i + 1, n):
            s -= M[i][j] * x[j]
        x[i] = s / M[i][i]

    return x


def fit_and_score_linear_regression(train_X, train_y, test_X, test_y):
    if len(train_X) != len(train_y):
        raise ValueError("train_X and train_y must have the same length")
    if len(test_X) != len(test_y):
        raise ValueError("test_X and test_y must have the same length")
    if len(train_X) == 0:
        raise ValueError("training set is empty")
    if len(test_X) == 0:
        raise ValueError("test set is empty")

    p = len(train_X[0])
    for row in train_X:
        if len(row) != p:
            raise ValueError("all training rows must have the same number of features")
    for row in test_X:
        if len(row) != p:
            raise ValueError("test rows must have the same number of features as training rows")

    # Design matrices with an intercept column
    X = [[1.0] + [float(v) for v in row] for row in train_X]
    y = [float(v) for v in train_y]
    X_test = [[1.0] + [float(v) for v in row] for row in test_X]
    y_test = [float(v) for v in test_y]

    m = p + 1

    # Normal equations: (X^T X) theta = X^T y
    XTX = [[0.0] * m for _ in range(m)]
    XTy = [0.0] * m

    for i in range(len(X)):
        row = X[i]
        yi = y[i]
        for j in range(m):
            XTy[j] += row[j] * yi
            for k in range(m):
                XTX[j][k] += row[j] * row[k]

    theta = _solve_linear_system(XTX, XTy)

    predictions = [
        sum(row[j] * theta[j] for j in range(m))
        for row in X_test
    ]

    mean_y = sum(y_test) / len(y_test)
    ss_tot = sum((yi - mean_y) ** 2 for yi in y_test)
    ss_res = sum((y_test[i] - predictions[i]) ** 2 for i in range(len(y_test)))

    if ss_tot == 0.0:
        return 1.0 if ss_res == 0.0 else 0.0

    return float(1.0 - ss_res / ss_tot)
