import math

def merge_and_standardize(rows1, rows2):
    # Discover feature columns, preserving order of first appearance.
    cols1 = []
    for row in rows1:
        for key in row:
            if key != 'id' and key not in cols1:
                cols1.append(key)

    cols2 = []
    for row in rows2:
        for key in row:
            if key != 'id' and key not in cols2:
                cols2.append(key)

    all_cols = ['id'] + cols1 + cols2

    # Raw outer join on 'id'.
    merged = {}
    for row in rows1:
        rid = row['id']
        entry = merged.setdefault(rid, {'id': rid})
        for col in cols1:
            entry[col] = row.get(col)

    for row in rows2:
        rid = row['id']
        entry = merged.setdefault(rid, {'id': rid})
        for col in cols2:
            entry[col] = row.get(col)

    # Ensure every merged row has every column.
    for entry in merged.values():
        for col in all_cols:
            entry.setdefault(col, None)

    # Standardize first-table feature columns using population std.
    for col in cols1:
        vals = []
        for entry in merged.values():
            v = entry.get(col)
            if v is not None:
                vals.append(v)

        n = len(vals)
        if n == 0:
            continue

        mean = sum(vals) / n
        if max(vals) == min(vals):
            std = 0.0
        else:
            std = math.sqrt(sum((v - mean) ** 2 for v in vals) / n)

        for entry in merged.values():
            v = entry.get(col)
            if v is None:
                continue
            entry[col] = 0.0 if std == 0.0 else (v - mean) / std

    # Return rows sorted by id.
    return [
        {col: merged[rid].get(col) for col in all_cols}
        for rid in sorted(merged)
    ]
