def seasonal_decomposition(values, period, model):
    values = list(values)
    n = len(values)

    if not isinstance(period, int) or period <= 0:
        raise ValueError("period must be a positive integer")
    if n < 2 * period:
        raise ValueError("series has fewer than two complete periods")
    if model not in ("additive", "multiplicative"):
        raise ValueError("model must be 'additive' or 'multiplicative'")

    # Centered moving average trend
    trend = [None] * n
    half = period // 2

    if period % 2 == 1:
        # Odd period: simple centered moving average
        for i in range(half, n - half):
            trend[i] = sum(values[i - half:i + half + 1]) / period
    else:
        # Even period: average of two adjacent period-length moving averages
        for i in range(half, n - half):
            ma1 = sum(values[i - half:i + half]) / period
            ma2 = sum(values[i - half + 1:i + half + 1]) / period
            trend[i] = (ma1 + ma2) / 2

    # Detrended series
    if model == "additive":
        detrended = [
            None if t is None else values[i] - t
            for i, t in enumerate(trend)
        ]
    else:  # multiplicative
        if any(t == 0 for t in trend if t is not None):
            raise ValueError("multiplicative decomposition requires non-zero trend values")
        detrended = [
            None if t is None else values[i] / t
            for i, t in enumerate(trend)
        ]

    # Raw seasonal indices for each phase
    raw = []
    for s in range(period):
        phase_values = [
            detrended[i]
            for i in range(s, n, period)
            if detrended[i] is not None
        ]
        raw.append(sum(phase_values) / len(phase_values))

    mean_raw = sum(raw) / period

    if model == "additive":
        seasonal_indices = [r - mean_raw for r in raw]
        seasonal = [seasonal_indices[i % period] for i in range(n)]
        residual = [
            None if t is None else values[i] - t - seasonal[i]
            for i, t in enumerate(trend)
        ]
    else:
        if mean_raw == 0:
            raise ValueError("cannot normalize multiplicative seasonal indices to average 1")
        seasonal_indices = [r / mean_raw for r in raw]
        seasonal = [seasonal_indices[i % period] for i in range(n)]
        residual = [
            None if t is None else values[i] / (t * seasonal[i])
            for i, t in enumerate(trend)
        ]

    return {"trend": trend, "seasonal": seasonal, "residual": residual}
```

For odd periods the trend is a simple centered moving average. For even periods it uses the usual 2×period centered moving average. The seasonal component is periodic and therefore defined for every index; the trend and residual are `None` at the ends where the centered moving average cannot be computed.

