def scale_table_columns(data):
    if not data:
        return {}

    n = len(next(iter(data.values())))
    keep = [
        i for i in range(n)
        if all(data[col][i] is not None for col in data)
    ]

    if not keep:
        return {col: [] for col in data}

    result = {}
    for col, values in data.items():
        vals = [values[i] for i in keep]
        lo = min(vals)
        hi = max(vals)

        if lo == hi:
            result[col] = [0.0] * len(vals)
        else:
            result[col] = [(v - lo) / (hi - lo) for v in vals]

    return result
```

