def distribution_summary(values):
    vals = sorted(values)
    n = len(vals)
    if n == 0:
        raise ValueError("values must not be empty")

    lo, hi = vals[0], vals[-1]

    # Histogram: 10 equal-width bins from min to max; max goes in the last bin.
    counts = [0] * 10
    if lo == hi:
        counts[9] = n
    else:
        width = (hi - lo) / 10.0
        for v in vals:
            if v == hi:
                idx = 9
            else:
                idx = int((v - lo) / width)
                if idx < 0:
                    idx = 0
                elif idx > 9:
                    idx = 9
            counts[idx] += 1

    # Linear interpolation quartiles: position = (n - 1) * p
    def quantile(p):
        pos = (n - 1) * p
        i = int(pos)
        frac = pos - i
        if frac == 0.0:
            return float(vals[i])
        return float(vals[i] + frac * (vals[i + 1] - vals[i]))

    q1 = quantile(0.25)
    median = quantile(0.50)
    q3 = quantile(0.75)

    iqr = q3 - q1
    lower_fence = q1 - 1.5 * iqr
    upper_fence = q3 + 1.5 * iqr

    within = [v for v in vals if lower_fence <= v <= upper_fence]
    outliers = [float(v) for v in vals if v < lower_fence or v > upper_fence]

    return {
        "counts": counts,
        "q1": q1,
        "median": median,
        "q3": q3,
        "whisker_low": float(min(within)),
        "whisker_high": float(max(within)),
        "outliers": outliers,
    }
