def standardize_numeric_columns(data):
    result = {}

    for key, column in data.items():
        # Try to convert every value to float.
        try:
            nums = [float(v) for v in column]
        except (TypeError, ValueError, OverflowError):
            # Not fully numeric: leave the column unchanged.
            result[key] = column
            continue

        n = len(nums)

        # Empty column: nothing to standardize.
        if n == 0:
            result[key] = column
            continue

        # Constant column: z-scores are all zero.
        if all(v == nums[0] for v in nums):
            result[key] = [0.0] * n
            continue

        # Mean and population standard deviation.
        mean = sum(nums) / n
        variance = sum((v - mean) ** 2 for v in nums) / n
        std = variance ** 0.5

        if std == 0.0:
            result[key] = [0.0] * n
        else:
            result[key] = [(v - mean) / std for v in nums]

    return result
