from fractions import Fraction

def weather_column_summary(column, data):
    col_index = {
        'Temperature': 1,
        'Humidity': 2,
        'Wind Speed': 3,
        'Precipitation': 4,
    }

    values = [row[col_index[column]] for row in data]

    if not values:
        return {
            'sum': 0,
            'mean': None,
            'min': None,
            'max': None,
            'histogram': [0] * 10,
        }

    total = sum(values)
    mn = min(values)
    mx = max(values)

    histogram = [0] * 10

    if mn == mx:
        # Only the last bin can contain the maximum.
        histogram[9] = len(values)
    else:
        # Use Fraction to avoid floating-point bin-edge issues.
        mn_f = Fraction(str(mn))
        mx_f = Fraction(str(mx))
        width = (mx_f - mn_f) / 10

        for v in values:
            v_f = Fraction(str(v))
            if v_f == mx_f:
                histogram[9] += 1
            else:
                pos = (v_f - mn_f) / width
                bin_idx = pos.numerator // pos.denominator
                if bin_idx < 0:
                    bin_idx = 0
                elif bin_idx > 9:
                    bin_idx = 9
                histogram[bin_idx] += 1

    return {
        'sum': total,
        'mean': total / len(values),
        'min': mn,
        'max': mx,
        'histogram': histogram,
    }
