def association_chi_square(left, right):
    left_map = dict(left)
    right_map = dict(right)

    common_ids = left_map.keys() & right_map.keys()
    joined = [(left_map[i], right_map[i]) for i in common_ids]

    if not joined:
        return (0.0, 0)

    left_cats = list(dict.fromkeys(lc for lc, _ in joined))
    right_cats = list(dict.fromkeys(rc for _, rc in joined))

    counts = {lc: {rc: 0 for rc in right_cats} for lc in left_cats}
    for lc, rc in joined:
        counts[lc][rc] += 1

    n = len(joined)

    row_totals = {lc: sum(counts[lc].values()) for lc in left_cats}
    col_totals = {rc: sum(counts[lc][rc] for lc in left_cats) for rc in right_cats}

    statistic = 0.0
    for lc in left_cats:
        for rc in right_cats:
            expected = row_totals[lc] * col_totals[rc] / n
            statistic += (counts[lc][rc] - expected) ** 2 / expected

    dof = (len(left_cats) - 1) * (len(right_cats) - 1)

    return statistic, dof
```

