from datetime import datetime
from zoneinfo import ZoneInfo

def publication_hour_stats(articles, timezone):
    if not articles:
        raise ValueError("articles list is empty")

    # Validate required keys before touching the timezone
    for article in articles:
        if not isinstance(article, dict) or "category" not in article or "published_time" not in article:
            raise ValueError("each article must be a dict with 'category' and 'published_time'")

    tz = ZoneInfo(timezone)
    hours_by_category = {}

    for article in articles:
        category = article["category"]
        published_time = article["published_time"]

        if not isinstance(published_time, str):
            raise ValueError("published_time must be an ISO 8601 string")

        # Accept trailing 'Z' as UTC
        if published_time.endswith(("Z", "z")):
            published_time = published_time[:-1] + "+00:00"

        dt = datetime.fromisoformat(published_time)

        if dt.tzinfo is None:
            raise ValueError("published_time must include a UTC offset")

        local_hour = dt.astimezone(tz).hour
        hours_by_category.setdefault(category, []).append(local_hour)

    result = {}
    for category in sorted(hours_by_category, key=str):
        hours = hours_by_category[category]
        result[category] = {
            "count": len(hours),
            "mean": sum(hours) / len(hours),
            "min": min(hours),
            "max": max(hours),
        }

    return result
