from collections import Counter

def _squared_distance(a, b):
    return (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2

def _assign(points, centroids):
    assignments = []
    for p in points:
        best_idx = 0
        best_dist = _squared_distance(p, centroids[0])
        for i in range(1, len(centroids)):
            d = _squared_distance(p, centroids[i])
            if d < best_dist:
                best_idx = i
                best_dist = d
        assignments.append(best_idx)
    return assignments

def cluster_unique_points(points, n_clusters):
    points = [tuple(p) for p in points]

    counts = Counter(points)
    duplicates = {p: c for p, c in counts.items() if c > 1}

    distinct = sorted(set(points))
    if not distinct or n_clusters <= 0:
        return duplicates, []

    k = min(int(n_clusters), len(distinct))
    if k <= 0:
        return duplicates, []

    # Deterministic initial centroids: first k distinct points
    centroids = [list(p) for p in distinct[:k]]
    assignments = None

    for _ in range(100):
        new_assignments = _assign(distinct, centroids)
        if new_assignments == assignments:
            break
        assignments = new_assignments

        new_centroids = [None] * k
        for i in range(k):
            members = [distinct[j] for j, a in enumerate(assignments) if a == i]
            if members:
                new_centroids[i] = [
                    sum(p[0] for p in members) / len(members),
                    sum(p[1] for p in members) / len(members),
                ]

        # Reinitialize any empty cluster to a far-away point
        empty = [i for i, c in enumerate(new_centroids) if c is None]
        if empty:
            chosen = set()
            for c in new_centroids:
                if c is not None:
                    for p in distinct:
                        if _squared_distance(p, c) == 0:
                            chosen.add(p)

            for i in empty:
                best_idx = -1
                best_d = -1.0
                for j, p in enumerate(distinct):
                    if p in chosen:
                        continue
                    d = _squared_distance(p, centroids[assignments[j]])
                    if d > best_d:
                        best_d = d
                        best_idx = j

                if best_idx == -1:
                    best_idx = max(
                        range(len(distinct)),
                        key=lambda j: _squared_distance(distinct[j], centroids[assignments[j]])
                    )

                new_centroids[i] = list(distinct[best_idx])
                chosen.add(distinct[best_idx])

        centroids = new_centroids

    assignments = _assign(distinct, centroids)

    clusters = [[] for _ in range(k)]
    for p, a in zip(distinct, assignments):
        clusters[a].append(p)

    clusters = [sorted(cluster) for cluster in clusters if cluster]
    clusters.sort()

    return duplicates, clusters
```

