import csv
from io import StringIO

def _is_numeric(value):
    try:
        float(value)
        return True
    except (TypeError, ValueError):
        return False

def _to_number(value):
    try:
        return int(value)
    except ValueError:
        return float(value)

def sort_csv_rows(csv_text, sort_by_column='title'):
    reader = csv.DictReader(StringIO(csv_text), restval='')
    fieldnames = reader.fieldnames or []
    rows = list(reader)

    if not rows:
        return []

    # A column is numeric only if every data value in it is numeric.
    numeric_cols = {
        col for col in fieldnames
        if all(_is_numeric(row[col]) for row in rows)
    }

    result = [
        {
            col: _to_number(row[col]) if col in numeric_cols else row[col]
            for col in fieldnames
        }
        for row in rows
    ]

    result.sort(key=lambda row: row[sort_by_column])
    return result
