import cmath
import math

def spectrum_magnitude_histogram(pairs):
    values = [value for _, value in pairs]
    n = len(values)

    if n == 0:
        return ([], [])

    # DFT: X_k = sum_{t=0}^{n-1} x_t * exp(-2*pi*i*k*t/n)
    roots = [cmath.exp(-2j * math.pi * i / n) for i in range(n)]

    magnitudes = []
    for k in range(n):
        coeff = 0j
        for t, x in enumerate(values):
            coeff += x * roots[(k * t) % n]
        magnitudes.append(abs(coeff))

    lo = min(magnitudes)
    hi = max(magnitudes)
    width = (hi - lo) / 10.0

    counts = [0] * 10

    if width == 0.0:
        # All magnitudes are identical; the last bin includes the right edge.
        counts[-1] = n
    else:
        for m in magnitudes:
            idx = int((m - lo) / width)
            if idx < 0:
                idx = 0
            elif idx >= 10:
                idx = 9
            counts[idx] += 1

    return (magnitudes, counts)
