import xml.etree.ElementTree as ET


def xml_to_dict(xml):
    """
    Parse an XML string into nested Python dicts.

    Returns {root_tag: value}. Malformed XML raises ValueError.
    """
    try:
        root = ET.fromstring(xml)
    except ET.ParseError as exc:
        raise ValueError(f"Malformed XML: {exc}") from exc

    return {root.tag: _element_to_value(root)}


def _element_to_value(elem):
    text = _direct_text(elem)

    # Leaf with no attributes and no children: just its text, or None.
    if not elem.attrib and len(elem) == 0:
        return text

    result = {}

    # Attributes
    for attr, value in elem.attrib.items():
        result["@" + attr] = value

    # Child elements; repeated tags become lists in document order.
    for child in elem:
        child_value = _element_to_value(child)
        if child.tag in result:
            existing = result[child.tag]
            if isinstance(existing, list):
                existing.append(child_value)
            else:
                result[child.tag] = [existing, child_value]
        else:
            result[child.tag] = child_value

    # Text directly under this element, if any.
    if text is not None:
        result["#text"] = text

    return result


def _direct_text(elem):
    """All text directly inside elem, including text around children, trimmed."""
    parts = []
    if elem.text:
        parts.append(elem.text)
    for child in elem:
        if child.tail:
            parts.append(child.tail)

    text = "".join(parts).strip()
    return text if text else None
