from numbers import Real

def row_averages_and_correlations(data):
    # Validate input
    if not isinstance(data, list) or not data:
        raise ValueError("data must be a non-empty list of rows")
    if not all(isinstance(row, list) for row in data):
        raise ValueError("each row must be a list")

    n_cols = len(data[0])
    if n_cols == 0:
        raise ValueError("each row must contain at least one number")

    for row in data:
        if len(row) != n_cols:
            raise ValueError("data must be rectangular")
        for value in row:
            if isinstance(value, bool) or not isinstance(value, Real):
                raise ValueError("each entry must be a number")

    n_rows = len(data)

    # Row averages
    averages = [float(sum(row) / len(row)) for row in data]

    # Extract columns
    columns = [[row[c] for row in data] for c in range(n_cols)]

    # Precompute column means and sums of squared deviations
    col_means = [sum(col) / n_rows for col in columns]
    col_ss = [
        sum((x - mean) ** 2 for x in col)
        for col, mean in zip(columns, col_means)
    ]

    # Build Pearson correlation matrix
    corr = [[0.0] * n_cols for _ in range(n_cols)]
    for i in range(n_cols):
        corr[i][i] = 1.0
        for j in range(i + 1, n_cols):
            num = sum(
                (x - col_means[i]) * (y - col_means[j])
                for x, y in zip(columns[i], columns[j])
            )
            den = (col_ss[i] * col_ss[j]) ** 0.5
            r = float(num / den) if den != 0 else float("nan")
            corr[i][j] = r
            corr[j][i] = r

    return averages, corr
