import math

def standardized_tensor_product(P, T):
    if not P or not T:
        raise ValueError("P and T must not be empty")

    m = len(P)
    k = len(P[0])

    if any(len(row) != k for row in P):
        raise ValueError("P must be rectangular")
    if k != len(T):
        raise ValueError("P's number of columns must match T's first dimension")

    n = len(T[0])
    if n == 0:
        raise ValueError("T must not be empty")

    p = len(T[0][0])
    if p == 0:
        raise ValueError("T must not be empty")

    # Ensure T is rectangular
    for i in range(k):
        if len(T[i]) != n:
            raise ValueError("T must be rectangular")
        for j in range(n):
            if len(T[i][j]) != p:
                raise ValueError("T must be rectangular")

    # Build the n x (m*p) table
    table = []
    for j in range(n):
        row = []
        for i in range(m):
            for c in range(p):
                total = 0.0
                for r in range(k):
                    total += P[i][r] * T[r][j][c]
                row.append(total)
        table.append(row)

    n_rows = n
    n_cols = m * p

    means = [0.0] * n_cols
    stds = [0.0] * n_cols

    # Standardize each column using population standard deviation
    for c in range(n_cols):
        col = [table[r][c] for r in range(n_rows)]

        # Zero variance column becomes all zeros
        if all(x == col[0] for x in col):
            continue

        mean = sum(col) / n_rows
        variance = sum((x - mean) ** 2 for x in col) / n_rows
        means[c] = mean
        stds[c] = math.sqrt(variance)

    result = []
    for r in range(n_rows):
        new_row = []
        for c in range(n_cols):
            if stds[c] == 0.0:
                new_row.append(0.0)
            else:
                new_row.append((table[r][c] - means[c]) / stds[c])
        result.append(new_row)

    return result
