def scale_by_group_with_histogram(ids, ages, incomes):
    n = len(ids)
    if n == 0:
        raise ValueError("no rows")
    if len(ages) != n or len(incomes) != n:
        raise ValueError("ids, ages, and incomes must have the same length")

    # First pass: per-group min and max for age and income
    age_min, age_max = {}, {}
    inc_min, inc_max = {}, {}

    for i, g in enumerate(ids):
        a = ages[i]
        inc = incomes[i]

        if g not in age_min:
            age_min[g] = age_max[g] = a
            inc_min[g] = inc_max[g] = inc
        else:
            if a < age_min[g]:
                age_min[g] = a
            if a > age_max[g]:
                age_max[g] = a
            if inc < inc_min[g]:
                inc_min[g] = inc
            if inc > inc_max[g]:
                inc_max[g] = inc

    scaled = []
    counts = [0] * 10

    # Second pass: scale each row and update income histogram
    for i, g in enumerate(ids):
        a = ages[i]
        inc = incomes[i]

        age_span = age_max[g] - age_min[g]
        inc_span = inc_max[g] - inc_min[g]

        if age_span == 0:
            scaled_age = 0.0
        else:
            scaled_age = a / age_span - age_min[g] / age_span

        if inc_span == 0:
            scaled_inc = 0.0
        else:
            scaled_inc = inc / inc_span - inc_min[g] / inc_span

        # Guard against tiny floating-point overshoots
        scaled_age = min(1.0, max(0.0, scaled_age))
        scaled_inc = min(1.0, max(0.0, scaled_inc))

        scaled.append([scaled_age, scaled_inc])

        # Ten equal-width bins over [0, 1]; last bin includes 1.0
        idx = int(scaled_inc * 10)
        if idx < 0:
            idx = 0
        elif idx > 9:
            idx = 9
        counts[idx] += 1

    return scaled, counts
