import csv
import io

def _is_float(value):
    try:
        float(value)
        return True
    except ValueError:
        return False

def fill_missing_with_column_mean(csv_text):
    if not csv_text.strip():
        return {}

    reader = csv.reader(io.StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        return {}

    width = len(header)
    rows = []

    for row in reader:
        if len(row) < width:
            row += [''] * (width - len(row))
        elif len(row) > width:
            row = row[:width]
        rows.append(row)

    if not rows:
        return {col: [] for col in header}

    result = {}

    for i, col in enumerate(header):
        values = [row[i] for row in rows]
        present = [v for v in values if v != '']

        if present and all(_is_float(v) for v in present):
            nums = [float(v) for v in present]
            mean = sum(nums) / len(nums)
            result[col] = [float(v) if v != '' else mean for v in values]
        else:
            result[col] = [v if v != '' else None for v in values]

    return result
