def encode_and_standardize(data, replacements):
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    result = {}

    for col, values in data.items():
        # Step 1: apply replacements
        vals = [replacements.get(v, v) for v in values]

        # Step 2: encode any column that contains strings
        if any(isinstance(v, str) for v in vals):
            distinct = sorted(set(vals), key=lambda x: (isinstance(x, str), str(x)))
            code_map = {v: i for i, v in enumerate(distinct)}
            vals = [code_map[v] for v in vals]

        # Step 3: standardize using sample standard deviation
        n = len(vals)
        if n == 0:
            result[col] = []
            continue

        mean = sum(vals) / n

        if n > 1:
            variance = sum((x - mean) ** 2 for x in vals) / (n - 1)
            std = variance ** 0.5
        else:
            std = 0.0

        if std == 0.0:
            result[col] = [0.0] * n
        else:
            result[col] = [(x - mean) / std for x in vals]

    return result
