from numbers import Number
import math

def correlation_without_column(data, column):
    def is_number(v):
        # Treat bool and complex as non-numeric for correlation purposes.
        return isinstance(v, Number) and not isinstance(v, (bool, complex))

    numeric_cols = {}

    for name, values in data.items():
        if name == column:
            continue

        values = list(values)
        if values and all(is_number(v) for v in values):
            numeric_cols[name] = [float(v) for v in values]

    if not numeric_cols:
        return None

    names = list(numeric_cols.keys())
    n = len(numeric_cols[names[0]])

    centered = {}
    ss = {}

    for name in names:
        vals = numeric_cols[name]
        mean = sum(vals) / n
        c = [v - mean for v in vals]
        centered[name] = c
        ss[name] = sum(x * x for x in c)

    result = {name: {} for name in names}

    for i, x in enumerate(names):
        for j in range(i, len(names)):
            y = names[j]

            if i == j:
                r = 1.0
            else:
                denom = math.sqrt(ss[x] * ss[y])
                if denom == 0.0:
                    r = 0.0
                else:
                    r = sum(centered[x][k] * centered[y][k] for k in range(n)) / denom
                    # Clamp tiny floating-point overshoots.
                    if r > 1.0:
                        r = 1.0
                    elif r < -1.0:
                        r = -1.0

            result[x][y] = r
            result[y][x] = r

    return result
