    for student, row in zip(students, grades):
        student_grades = {
            subject: float(grade)
            for subject, grade in zip(subjects, row)
        }
        student_grades["Average Grade"] = sum(student_grades.values()) / len(subjects)
        report[student] = student_grades

    average_row = {
        subject: sum(float(row[j]) for row in grades) / len(students)
        for j, subject in enumerate(subjects)
    }
    average_row["Average Grade"] = (
        sum(report[student]["Average Grade"] for student in students) / len(students)
    )

    report["Average"] = average_row
    return report
