import statistics

def replace_and_standardize(data, features, mapping):
    missing = [f for f in features if f not in data]
    if missing:
        raise ValueError(f"Missing feature columns: {missing}")

    # Replace values throughout the whole table first
    replaced = {
        col: [mapping.get(value, value) for value in values]
        for col, values in data.items()
    }

    feature_set = set(features)
    result = {}
    standardized_cache = {}

    # Iterate over replaced columns to preserve original column order
    for col, values in replaced.items():
        if col in feature_set:
            if col not in standardized_cache:
                n = len(values)
                if n == 0:
                    standardized_cache[col] = []
                else:
                    mean = statistics.mean(values)
                    std = statistics.pstdev(values)  # population standard deviation
                    if std == 0:
                        standardized_cache[col] = [0.0] * n
                    else:
                        standardized_cache[col] = [(x - mean) / std for x in values]
            result[col] = standardized_cache[col]
        else:
            result[col] = values

    return result
