def top_ngrams(text, n, top_k):
    if n <= 0 or top_k <= 0:
        return []

    # Lowercase and extract alphanumeric words; punctuation acts as a separator.
    words = []
    current = []
    for ch in text.lower():
        if ch.isalnum():
            current.append(ch)
        elif current:
            words.append("".join(current))
            current = []
    if current:
        words.append("".join(current))

    counts = {}
    first_seen = {}

    for i in range(len(words) - n + 1):
        gram = " ".join(words[i:i + n])
        if gram not in counts:
            counts[gram] = 0
            first_seen[gram] = i
        counts[gram] += 1

    ranked = sorted(
        counts.items(),
        key=lambda item: (-item[1], first_seen[item[0]])
    )

    return ranked[:top_k]
```

