from html.parser import HTMLParser


class _TableParser(HTMLParser):
    """Collect rows from the table with a specific id."""

    def __init__(self, table_id):
        super().__init__(convert_charrefs=True)  # decodes entities automatically
        self.table_id = table_id
        self.table_stack = []      # ids of currently open <table> elements
        self.found = False
        self.rows = []
        self.current_row = None
        self.current_cell = None

    def _in_target(self):
        return bool(self.table_stack) and self.table_stack[-1] == self.table_id

    def _flush_cell(self):
        if self.current_cell is not None:
            text = ''.join(self.current_cell).strip()
            if self.current_row is not None:
                self.current_row.append(text)
            self.current_cell = None

    def _flush_row(self):
        if self.current_row is not None:
            self.rows.append(self.current_row)
            self.current_row = None

    def handle_starttag(self, tag, attrs):
        if tag == 'table':
            tid = dict(attrs).get('id')
            self.table_stack.append(tid)
            if tid == self.table_id:
                self.found = True

        elif tag == 'tr':
            if self._in_target():
                self._flush_cell()
                self._flush_row()
                self.current_row = []

        elif tag in ('td', 'th'):
            if self._in_target() and self.current_row is not None:
                self._flush_cell()
                self.current_cell = []

    def handle_endtag(self, tag):
        if tag == 'table':
            if self._in_target():
                self._flush_cell()
                self._flush_row()
            if self.table_stack:
                self.table_stack.pop()

        elif tag == 'tr':
            if self._in_target() and self.current_row is not None:
                self._flush_cell()
                self._flush_row()

        elif tag in ('td', 'th'):
            if self._in_target() and self.current_cell is not None:
                self._flush_cell()

    def handle_data(self, data):
        # Only collect text inside a cell of the target table.
        if self.current_cell is not None:
            self.current_cell.append(data)


def html_table_records(html, table_id):
    parser = _TableParser(table_id)
    parser.feed(html)
    parser.close()

    # Flush any unclosed row/cell at the end of the document.
    parser._flush_cell()
    parser._flush_row()

    if not parser.found:
        raise ValueError(f"No table with id {table_id!r}")

    rows = parser.rows
    if not rows:
        return []

    headers = rows[0]
    records = []

    for row in rows[1:]:
        record = {}
        for i, header in enumerate(headers):
            record[header] = row[i] if i < len(row) else ''
        records.append(record)

    return records
