import csv
import io
import re

_INT_RE = re.compile(r"[+-]?\d+")
_NUM_RE = re.compile(r"[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?")

def _is_int(value: str) -> bool:
    return _INT_RE.fullmatch(value.strip()) is not None

def _is_numeric(value: str) -> bool:
    return _NUM_RE.fullmatch(value.strip()) is not None

def concat_csv_tables(csv_texts):
    if not csv_texts:
        raise ValueError("csv_texts must not be empty")

    headers = None
    rows = []

    for text in csv_texts:
        reader = csv.DictReader(io.StringIO(text), restval="")
        if reader.fieldnames is None:
            continue
        if headers is None:
            headers = list(reader.fieldnames)
        rows.extend(reader)

    if headers is None:
        return []

    # Determine which columns are fully numeric.
    numeric_columns = []
    for col in headers:
        values = [row.get(col, "") for row in rows]
        numeric_columns.append(all(_is_numeric(v) for v in values))

    result = []
    for row in rows:
        out = {}
        for i, col in enumerate(headers):
            value = row.get(col, "")
            if numeric_columns[i]:
                if _is_int(value):
                    out[col] = int(value.strip())
                else:
                    out[col] = float(value.strip())
            else:
                out[col] = value
        result.append(out)

    return result
