def csv_mean_median(csv_text):
    if not csv_text:
        return (None, None)

    reader = csv.reader(io.StringIO(csv_text))
    nums = []
    header_seen = False

    for row in reader:
        if not row or not row[0].strip():
            continue  # ignore blank lines

        if not header_seen:
            header_seen = True
            continue  # skip the header row

        cell = row[0].strip()
        try:
            value = float(cell)
        except ValueError:
            continue  # ignore non-numeric values

        if math.isfinite(value):
            nums.append(value)

    if not nums:
        return (None, None)

    mean = sum(nums) / len(nums)

    ordered = sorted(nums)
    n = len(ordered)
    if n % 2:
        median = float(ordered[n // 2])
    else:
        median = (ordered[n // 2 - 1] + ordered[n // 2]) / 2.0

    return (mean, median)
