            self._in_script = False
            self._current = []

    def handle_data(self, data):
        if self._in_script:
            self._current.append(data)

    def close(self):
        super().close()
        if self._in_script:
            self.scripts.append("".join(self._current))
            self._in_script = False
            self._current = []


def extract_script_dicts(html):
    parser = _ScriptExtractor()
    parser.feed(html)
    parser.close()

    result = []
    for body in parser.scripts:
        try:
            value = ast.literal_eval(body)
        except Exception:
            continue
        if isinstance(value, dict):
            result.append(value)

    return result
```

Example:

