import csv
from collections import Counter
from decimal import Decimal, InvalidOperation
from io import StringIO

def sales_report(csv_text):
    if not isinstance(csv_text, str):
        raise ValueError("csv_text must be a string")

    reader = csv.DictReader(StringIO(csv_text), skipinitialspace=True)
    if reader.fieldnames is not None:
        reader.fieldnames = [name.strip() for name in reader.fieldnames]

    seen = set()
    total = Decimal("0")
    category_counts = Counter()

    for row in reader:
        customer = row["Customer"].strip()
        if customer in seen:
            continue
        seen.add(customer)

        sales_raw = row["Sales"].strip()
        try:
            total += Decimal(sales_raw)
        except InvalidOperation:
            total += Decimal(sales_raw.replace(",", "").replace("$", ""))

        category = row["Category"].strip()
        category_counts[category] += 1

    if total == total.to_integral_value():
        total = int(total)
    else:
        total = float(total)

    most_popular = None
    if category_counts:
        most_popular = max(
            category_counts.items(),
            key=lambda item: (-item[1], item[0])
        )[0]

    return {"Total Sales": total, "Most Popular Category": most_popular}
