import math

def country_score_summary(records):
    if not records:
        raise ValueError("records is empty")

    required = {'Name', 'Country', 'Score'}
    seen_names = set()
    scores_by_country = {}

    for record in records:
        if not isinstance(record, dict) or not required.issubset(record):
            raise ValueError("record lacks required keys")

        name = record['Name']
        if name in seen_names:
            continue
        seen_names.add(name)

        country = record['Country']
        score = record['Score']
        scores_by_country.setdefault(country, []).append(score)

    def quantile(sorted_values, p):
        n = len(sorted_values)
        if n == 1:
            return float(sorted_values[0])

        pos = (n - 1) * p
        lower = math.floor(pos)
        upper = math.ceil(pos)

        if lower == upper:
            return float(sorted_values[lower])

        weight = pos - lower
        return float(
            sorted_values[lower] * (1 - weight) +
            sorted_values[upper] * weight
        )

    summary = {}
    for country, scores in scores_by_country.items():
        sorted_scores = sorted(scores)
        summary[country] = [
            float(sorted_scores[0]),
            quantile(sorted_scores, 0.25),
            quantile(sorted_scores, 0.5),
            quantile(sorted_scores, 0.75),
            float(sorted_scores[-1]),
        ]

    return summary
