from numbers import Number

def column_covariance(columns):
    if not columns:
        raise ValueError("table has no columns")

    cols = {name: list(col) for name, col in columns.items()}

    # Validate that all values are numeric.
    for name, vals in cols.items():
        for v in vals:
            if not isinstance(v, Number):
                raise TypeError(f"column {name!r} contains non-numeric value: {v!r}")

    # Validate row count and equal column lengths.
    lengths = {len(vals) for vals in cols.values()}
    if 0 in lengths:
        raise ValueError("table has no rows")
    if len(lengths) != 1:
        raise ValueError("columns must have equal length")

    n = next(iter(lengths))
    if n < 2:
        raise ValueError("table must have at least two rows")

    means = {name: sum(vals) / n for name, vals in cols.items()}

    result = {name: {} for name in cols}
    for a in cols:
        for b in cols:
            cov = sum(
                (x - means[a]) * (y - means[b])
                for x, y in zip(cols[a], cols[b])
            ) / (n - 1)
            result[a][b] = cov

    return result
