import math

def summarize_from_user(records):
    values = []

    for record in records:
        if isinstance(record, dict) and "from_user" in record:
            value = record["from_user"]
            if not isinstance(value, (int, float)):
                raise ValueError("from_user value must be numeric")
            values.append(value)

    if not values:
        return {
            "mean": None,
            "median": None,
            "min": None,
            "max": None,
            "std": None,
        }

    n = len(values)
    mean = sum(values) / n

    ordered = sorted(values)
    mid = n // 2
    if n % 2 == 1:
        median = ordered[mid]
    else:
        median = (ordered[mid - 1] + ordered[mid]) / 2

    variance = sum((x - mean) ** 2 for x in values) / n
    std = math.sqrt(variance)

    return {
        "mean": float(mean),
        "median": float(median),
        "min": float(min(values)),
        "max": float(max(values)),
        "std": float(std),
    }
