def summarize_student_records(data):
    required = ('Name', 'Age', 'Score')
    for key in required:
        if key not in data:
            raise ValueError(f"Missing required key: {key!r}")

    names = data['Name']
    ages = data['Age']
    scores = data['Score']

    # Stable sort by name, then age
    records = sorted(
        ([name, age, score] for name, age, score in zip(names, ages, scores)),
        key=lambda rec: (rec[0], rec[1])
    )

    # Average score per student
    totals = {}
    counts = {}
    for name, _age, score in records:
        totals[name] = totals.get(name, 0) + score
        counts[name] = counts.get(name, 0) + 1

    avg_scores = {name: totals[name] / counts[name] for name in totals}

    # Most common age
    age_counts = {}
    for age in ages:
        age_counts[age] = age_counts.get(age, 0) + 1

    most_common_age = max(age_counts, key=age_counts.get) if age_counts else None

    return records, avg_scores, most_common_age
```

