import math

def row_distance_matrix(rows):
    # Validate that every element is an int or float
    for row in rows:
        for value in row:
            if not isinstance(value, (int, float)):
                raise TypeError("all elements must be int or float")

    n = len(rows)
    matrix = [[0.0] * n for _ in range(n)]

    for i in range(n):
        for j in range(i + 1, n):
            dist = math.sqrt(
                sum((a - b) ** 2 for a, b in zip(rows[i], rows[j]))
            )
            matrix[i][j] = dist
            matrix[j][i] = dist

