import io
import math

def _cube_root(x):
    # Preserve sign for negative numbers: cube root of -64 is -4.
    return math.copysign(abs(x) ** (1.0 / 3.0), x)

def csv_cube_roots(csv_text, columns):
    reader = csv.reader(io.StringIO(csv_text))
    header = next(reader, [])

    header_set = set(header)
    for col in columns:
        if col not in header_set:
            raise KeyError(col)

    data = {name: [] for name in header}

    for row in reader:
        for name, value in zip(header, row):
            try:
                num = float(value)
            except (TypeError, ValueError):
                raise ValueError(
                    f"Non-numeric value {value!r} in column {name!r}"
                ) from None
            data[name].append(num)

    cube_roots = {
        col: [_cube_root(v) for v in data[col]]
        for col in columns
    }

    return data, cube_roots
