def count_items_by_location(data, items, locations):
    """
    Count how many rows have each requested item at each requested location.

    Args:
        data: dict with 'Item' and 'Location' lists of equal length.
        items: list of items to count, or None for the default item list.
        locations: list of locations to count, or None for the default location list.

    Returns:
        dict mapping each location to a dict mapping each item to its count.
    """
    if 'Item' not in data or 'Location' not in data:
        raise ValueError("data must contain 'Item' and 'Location' keys")

    if items is None:
        items = ['apple', 'banana', 'grape', 'orange', 'pineapple']
    if locations is None:
        locations = ['store1', 'store2', 'store3', 'store4', 'store5']

    result = {
        loc: {item: 0 for item in items}
        for loc in locations
    }

    for item, loc in zip(data['Item'], data['Location']):
        if loc in result and item in result[loc]:
            result[loc][item] += 1

    return result
