def normalize_columns(data):
    if not isinstance(data, dict) or not data:
        raise ValueError("data must be a non-empty dict")

    normalized = {}

    for name, column in data.items():
        try:
            values = list(column)
        except TypeError:
            raise ValueError(f"column {name!r} must contain numbers") from None

        for value in values:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise ValueError(
                    f"column {name!r} contains non-numeric value: {value!r}"
                )

        if not values:
            normalized[name] = []
            continue

        low = min(values)
        high = max(values)

        if low == high:
            normalized[name] = [0.0] * len(values)
        else:
            span = high - low
            normalized[name] = [
                float((value - low) / span) for value in values
            ]

    return normalized
