from html.parser import HTMLParser

class _LinkParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = []        # each entry: [text_parts, href]
        self.open_links = []   # stack of currently open <a> entries

    def handle_starttag(self, tag, attrs):
        if tag == 'a':
            href = None
            for name, value in attrs:
                if name == 'href':
                    href = value
                    break
            link = [[], href]
            self.links.append(link)
            self.open_links.append(link)

    def handle_startendtag(self, tag, attrs):
        # Treat <a ... /> as an empty link
        if tag == 'a':
            self.handle_starttag(tag, attrs)
            self.handle_endtag(tag)

    def handle_endtag(self, tag):
        if tag == 'a' and self.open_links:
            self.open_links.pop()

    def handle_data(self, data):
        # Add text to all currently open <a> tags (handles nested tags)
        for link in self.open_links:
            link[0].append(data)


def extract_links(html):
    parser = _LinkParser()
    parser.feed(html)
    parser.close()
    return [(''.join(parts), href) for parts, href in parser.links]
