from html.parser import HTMLParser

class _FirstTableParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.found_table = False
        self.table_depth = 0
        self.headers = []
        self.rows = []
        self._in_cell = False
        self._cell_tag = None
        self._cell_text = []
        self._current_row = None
        self._row_has_td = False

    def _finish_cell(self):
        if not self._in_cell:
            return
        text = ''.join(self._cell_text).strip()
        if self._cell_tag == 'th':
            self.headers.append(text)
        elif self._cell_tag == 'td' and self._current_row is not None:
            self._current_row.append(text)
            self._row_has_td = True
        self._in_cell = False
        self._cell_tag = None
        self._cell_text = []

    def _finish_row(self):
        if self._current_row is not None and self._row_has_td:
            self.rows.append(self._current_row)
        self._current_row = None
        self._row_has_td = False

    def handle_starttag(self, tag, attrs):
        if tag == 'table':
            if not self.found_table and self.table_depth == 0:
                self.found_table = True
                self.table_depth = 1
            elif self.table_depth >= 1:
                self.table_depth += 1
            return

        if not self.found_table or self.table_depth != 1:
            return

        if tag == 'tr':
            if self._in_cell:
                self._finish_cell()
            self._finish_row()
            self._current_row = []
            self._row_has_td = False
        elif tag in ('th', 'td'):
            if self._in_cell:
                self._finish_cell()
            self._in_cell = True
            self._cell_tag = tag
            self._cell_text = []

    def handle_endtag(self, tag):
        if tag == 'table':
            if self.table_depth > 0:
                self.table_depth -= 1
                if self.table_depth == 0:
                    if self._in_cell:
                        self._finish_cell()
                    self._finish_row()
            return

        if not self.found_table or self.table_depth != 1:
            return

        if tag in ('th', 'td'):
            if self._in_cell and self._cell_tag == tag:
                self._finish_cell()
        elif tag == 'tr':
            if self._in_cell:
                self._finish_cell()
            self._finish_row()

    def handle_data(self, data):
        if self._in_cell and self.found_table and self.table_depth == 1:
            self._cell_text.append(data)

    def finalize(self):
        if self.found_table:
            if self._in_cell:
                self._finish_cell()
            self._finish_row()


def extract_first_table(html):
    parser = _FirstTableParser()
    parser.feed(html)
    parser.close()
    parser.finalize()

    if not parser.found_table:
        raise ValueError("No table found")
    if not parser.rows:
        raise ValueError("Table has no data rows")

    return parser.headers, parser.rows
```

