import math
from typing import List, Tuple

def row_zscores_and_correlation(
    data: List[List[float]]
) -> Tuple[List[List[float]], List[List[float]]]:
    if not data:
        return [], []

    # Row-wise z-scores using population standard deviation (divide by n)
    z = []
    for row in data:
        n = len(row)
        if n == 0:
            z.append([])
            continue

        mean = sum(row) / n
        std = math.sqrt(sum((x - mean) ** 2 for x in row) / n)
        z.append([(x - mean) / std for x in row])

    if not z or not z[0]:
        return z, []

    m = len(z)
    n = len(z[0])

    # Extract columns of the z-score matrix and centre them
    cols = [[z[r][c] for r in range(m)] for c in range(n)]
    centered = []
    for col in cols:
        col_mean = sum(col) / m
        centered.append([x - col_mean for x in col])

    ss = [sum(x * x for x in col) for col in centered]

    # Pearson correlation matrix between columns
    corr = [[0.0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i == j:
                corr[i][j] = 1.0
            else:
                denom = math.sqrt(ss[i] * ss[j])
                if denom == 0.0:
                    corr[i][j] = 0.0
                else:
                    corr[i][j] = sum(
                        centered[i][r] * centered[j][r] for r in range(m)
                    ) / denom

    return z, corr
