def standardize_filtered(data, age, weight):
    # Raises KeyError if either required column is missing
    if 'Age' not in data or 'Weight' not in data:
        raise KeyError("data must contain 'Age' and 'Weight'")

    age_col = data['Age']
    weight_col = data['Weight']

    keep = [
        i for i in range(len(age_col))
        if age_col[i] < age and weight_col[i] > weight
    ]

    if not keep:
        return {col: [] for col in data}

    result = {}
    for col, values in data.items():
        kept = [values[i] for i in keep]
        mean = sum(kept) / len(kept)
        variance = sum((x - mean) ** 2 for x in kept) / len(kept)
        std = variance ** 0.5

        if std == 0:
            result[col] = [0.0] * len(kept)
        else:
            result[col] = [(x - mean) / std for x in kept]

    return result
