    totals = {}
    counts = {}

    for row in reader:
        if not row:
            continue

        raw_value = row[value_idx] if value_idx < len(row) else ""

        # Blank value cells are ignored.
        if raw_value is None or raw_value.strip() == "":
            continue

        try:
            value = float(raw_value)
        except ValueError:
            raise ValueError(
                f"Non-numeric value in column {value_col!r}: {raw_value!r}"
            ) from None

        group = row[group_idx] if group_idx < len(row) else ""
        group_label = str(group)

        totals[group_label] = totals.get(group_label, 0.0) + value
        counts[group_label] = counts.get(group_label, 0) + 1

    return {
        label: totals[label] / counts[label]
        for label in totals
    }
