import math

def standardize_columns(data):
    result = {}

    for name, values in data.items():
        n = len(values)

        if n == 0:
            result[name] = ([], [0] * 20)
            continue

        mean = sum(values) / n
        variance = sum((x - mean) ** 2 for x in values) / n
        std = math.sqrt(variance)

        if std == 0:
            standardized = [0.0] * n
        else:
            standardized = [(x - mean) / std for x in values]

        lo = min(standardized)
        hi = max(standardized)
        counts = [0] * 20

        if hi == lo:
            counts[19] = n
        else:
            width = (hi - lo) / 20
            for v in standardized:
                if v == hi:
                    idx = 19
                else:
                    idx = int((v - lo) / width)
                    if idx < 0:
                        idx = 0
                    elif idx > 19:
                        idx = 19
                counts[idx] += 1

        result[name] = (standardized, counts)

    return result
```

