import math

def _is_numeric(v):
    return isinstance(v, (int, float))

def standardize_and_correlate(table):
    if not table:
        raise ValueError("table is empty")

    n = len(next(iter(table.values())))
    if n == 0:
        raise ValueError("table is empty")

    numeric_cols = [
        name for name, vals in table.items()
        if all(_is_numeric(v) for v in vals)
    ]
    if not numeric_cols:
        raise ValueError("no numeric columns")

    means = {}
    stds = {}
    for name in numeric_cols:
        vals = table[name]
        mu = sum(vals) / n
        variance = sum((v - mu) ** 2 for v in vals) / n
        means[name] = mu
        stds[name] = math.sqrt(variance)

    numeric_set = set(numeric_cols)
    standardized = {}

    for name, vals in table.items():
        if name in numeric_set:
            mu = means[name]
            sigma = stds[name]
            if sigma == 0.0:
                standardized[name] = [0.0] * n
            else:
                standardized[name] = [(v - mu) / sigma for v in vals]
        else:
            standardized[name] = list(vals)

    m = len(numeric_cols)
    corr = [[0.0] * m for _ in range(m)]

    for i, ci in enumerate(numeric_cols):
        corr[i][i] = 1.0
        xi = table[ci]
        mui = means[ci]
        si = stds[ci]

        for j in range(i + 1, m):
            cj = numeric_cols[j]
            yj = table[cj]
            muj = means[cj]
            sj = stds[cj]

            if si == 0.0 or sj == 0.0:
                r = 0.0
            else:
                num = sum((a - mui) * (b - muj) for a, b in zip(xi, yj))
                r = num / (n * si * sj)
                if r > 1.0:
                    r = 1.0
                elif r < -1.0:
                    r = -1.0

            corr[i][j] = corr[j][i] = r

    return standardized, corr
```

Example usage:

```python
standardize_and_correlate({
    'x': [1, 2, 3],
    'n': ['a', 'b', 'c'],
    'y': [3, 1, 2]
})
```

returns numeric columns standardized to mean 0 and population standard deviation 1, while string columns are left unchanged, and the correlation matrix of the numeric columns in table order.

