from html.parser import HTMLParser

class _TableRowParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.rows = []
        self._row_stack = []
        self._cell_stack = []   # each entry: [row_list, text_parts]
        self._th_depth = 0

    def handle_starttag(self, tag, attrs):
        if tag == "tr":
            row = []
            self.rows.append(row)
            self._row_stack.append(row)
        elif tag == "td":
            row = self._row_stack[-1] if self._row_stack else None
            self._cell_stack.append([row, []])
        elif tag == "th":
            self._th_depth += 1

    def handle_endtag(self, tag):
        if tag == "tr":
            if self._row_stack:
                self._row_stack.pop()
        elif tag == "td":
            if self._cell_stack:
                row, parts = self._cell_stack.pop()
                if row is not None:
                    row.append("".join(parts).strip())
        elif tag == "th":
            if self._th_depth > 0:
                self._th_depth -= 1

    def handle_data(self, data):
        # Ignore text inside <th>; otherwise append to all open <td> cells
        # so nested tags are treated as plain text.
        if self._th_depth == 0:
            for _, parts in self._cell_stack:
                parts.append(data)


def extract_table_rows(html):
    parser = _TableRowParser()
    parser.feed(html)
    parser.close()
    return parser.rows
```

