import json
from html import unescape
from html.parser import HTMLParser

class _TitleParser(HTMLParser):
    # Treat <title> like raw text so tags inside it are not parsed.
    CDATA_CONTENT_ELEMENTS = ("script", "style", "textarea", "title")

    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.found_title = False
        self.in_title = False
        self._raw_parts = []

    def handle_starttag(self, tag, attrs):
        if tag == "title" and not self.found_title:
            self.found_title = True
            self.in_title = True
            self._raw_parts = []

    def handle_endtag(self, tag):
        if tag == "title" and self.in_title:
            self.in_title = False

    def handle_data(self, data):
        if self.in_title:
            self._raw_parts.append(data)


def extract_title_json(html: str) -> str:
    parser = _TitleParser()
    parser.feed(html)
    parser.close()

    if not parser.found_title:
        title = None
    else:
        title = unescape("".join(parser._raw_parts))

    return json.dumps({"title": title}, ensure_ascii=False)
